entries[1215707] = { ["name"] = "Paladin Retribution 11.1 Class Set 2pc", ["text"] = "Approximately 10 procs per minute\nYour spells and abilities have a chance to activate a Winning Streak! increasing the damage of your Templar's Verdict and Divine Storm by 2% stacking up to 10 times. Spending Holy Power on damaging abilities has a 12% chance to remove Winning Streak!" }
