entries[1215710] = { ["name"] = "Shaman Enhancement 11.1 Class Set 2pc", ["text"] = "Approximately 10 procs per minute\nYour spells and abilities have a chance to activate a Winning Streak! increasing the damage of your Stormstrike, Lava Lash and Doom Winds by 5%, up to 25%. Maelstrom Weapon spenders have a 1.0% chance to remove Winning Streak! per Maelstrom Weapon spent." }
