entries[1215712] = { ["name"] = "Shaman Enhancement 11.1 Class Set 4pc", ["text"] = "When you lose your Winning Streak! the winds shift into Doom Winds for 3 sec. When Doom Winds deal damage, your next Crash Lightning deals 12.0% increased damage, up to 60.0%. This effect can be stored up to 10 stacks. Additionally, Crash Lightning deals 75% more damage to your main target.\n(100ms cooldown)" }
entries[1215713] = { ["name"] = "Warrior Arms 11.1 Class Set 2pc", ["text"] = "Approximately 10 procs per minute\nYour abilities have a chance to begin a Winning Streak! , increasing the damage of Overpower by 5%, stacking up to 10 times.\nOverpower has a 15% chance to end your Winning Streak!" }
entries[1215714] = { ["name"] = "Warrior Fury 11.1 Class Set 2pc", ["text"] = "Approximately 10 procs per minute\nYour abilities have a chance to start a Winning Streak! , increasing the damage of Rampage by 2%, stacking up to 10 times.\nRampage has a 15% chance to end your Winning Streak!" }
entries[1215715] = { ["name"] = "Warrior Fury 11.1 Class Set 4pc", ["text"] = "When you gain a stack of Winning Streak! you have an even chance to either cause your next Bloodthirst to deal 15% increased damage and have 25% increased chance to critically strike or cause your next Raging Blow to deal 15% increased damage and generate 2 additional Rage." }
entries[1215716] = { ["name"] = "Warrior Arms 11.1 Class Set 4pc", ["text"] = "When your Winning Streak! ends you gain 2% Haste and your Mortal Strike and Cleave damage is increased by 2% per stack of Winning Streak! you had for 12 sec." }
entries[1215717] = { ["name"] = "Monk Windwalker 11.1 Class Set 2pc", ["text"] = "Approximately 10 procs per minute\nYour spells and abilities have a chance to activate a Winning Streak! , increasing the damage of your Rising Sun Kick and Spinning Crane Kick by 3%, stacking up to 10 times. Rising Sun Kick and Spinning Crane Kick have a 15% chance to remove Winning Streak!" }
entries[1215718] = { ["name"] = "Monk Windwalker 11.1 Class Set 4pc", ["text"] = "Fists of Fury applies 1 stack of Winning Streak! when cast and when finished channeling completely. The damage of your next Fists of Fury is increased by 8% per stack when Winning Streak! is removed.\n\nYour Winning Streak! is always removed once it reaches max stacks." }
entries[1215719] = { ["name"] = "Rogue Assassination 11.1 Class Set 2pc", ["text"] = "Approximately 10 procs per minute\nYour spells and abilities have a chance to activate a Winning Streak! increasing the damage of your Envenom, Rupture, and Crimson Tempest by 3% stacking up to 10 times. Envenom, Rupture, and Crimson Tempest have a 15% chance to remove Winning Streak!" }
entries[1215720] = { ["name"] = "Rogue Outlaw 11.1 Class Set 2pc", ["text"] = "Approximately 8 procs per minute\nYour spells and abilities have a chance to activate a Winning Streak! increasing the damage of your Dispatch by 6% stacking up to 5 times. Dispatch has a 15% chance to remove Winning Streak!" }
entries[1215721] = { ["name"] = "Rogue Subtlety 11.1 Class Set 2pc", ["text"] = "Approximately 10 procs per minute\nYour spells and abilities have a chance to activate a Winning Streak! increasing the damage of your Eviscerate, Secret Technique, and Black Powder by 2% stacking up to 8 times. Eviscerate, Secret Technique, and Black Powder have a 15% chance to remove Winning Streak!" }
entries[1215722] = { ["name"] = "Rogue Subtlety 11.1 Class Set 4pc", ["text"] = "While Shadow Dance is active, you cannot lose Winning Streak! , gain an additional stack of Winning Streak! each time you would gain one, and deal an additional 2% Shadow Damage per Winning Streak! stack." }
entries[1215724] = { ["name"] = "Rogue Assassination 11.1 Class Set 4pc", ["text"] = "When you would lose Winning Streak! , you have a chance to instead gain maximum stacks of Winning Streak! for 4s. These cannot be removed and have 50% additional effect while immune to removal." }
entries[1215725] = { ["name"] = "Rogue Outlaw 11.1 Class Set 4pc", ["text"] = "Roll the Bones has a 40% increased chance of granting additional combat enhancements and also applies 1 stack of Winning Streak! for each combat enhancement granted.\n\nStacks applied by Roll the Bones can exceed the normal Winning Streak! maximum of 5." }
